actions.script:
import groovy.json.JsonOutput
import org.moqui.entity.EntityCondition

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_DEVICE_SAFETY_EXPOSURE',
                 startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([deviceId: deviceId]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    List physicalPortDrivers = ['DcdUsbPhysical', 'DcdSerialPhysical', 'DcdSdCardPhysical']
    List remoteAccessPurposes = ['DcpMaintenance', 'DcpDiagnostics']

    List<Map> vectorList = []
    ec.entity.find('moqui.device.DeviceConnection').condition('deviceId', deviceId).list().each { conn ->
        boolean isPhysicalPort = physicalPortDrivers.contains(conn.driverEnumId as String)
        boolean isRemoteAccess = remoteAccessPurposes.contains(conn.purposeEnumId as String)
        if (isPhysicalPort || isRemoteAccess) {
            vectorList.add([connectionName: conn.connectionName, driverEnumId: conn.driverEnumId,
                    purposeEnumId: conn.purposeEnumId,
                    vectorType: isPhysicalPort ? 'PHYSICAL_PORT' : 'REMOTE_ACCESS'])
        }
    }
    def flowOrCond = ec.entity.conditionFactory.makeCondition(
            [sourceDeviceId: deviceId, destDeviceId: deviceId] as Map,
            EntityCondition.ComparisonOperator.EQUALS, EntityCondition.JoinOperator.OR)
    ec.entity.find('org.moqui.cyber.CyberDeviceCommunicationFlow')
            .condition(flowOrCond)
            .list().each { flow ->
        vectorList.add([communicationFlowId: flow.communicationFlowId, protocolEnumId: flow.protocolEnumId,
                port: flow.port, vectorType: 'COMMUNICATION_FLOW'])
    }
    vectors = vectorList

    List<Map> safetyFeatureList = []
    def deviceValue = ec.entity.find('moqui.device.Device').condition('deviceId', deviceId).one()
    String assetId = deviceValue?.assetId as String
    String productId = assetId ? (ec.entity.find('mantle.product.asset.Asset')
            .condition('assetId', assetId).one()?.productId as String) : null
    if (productId) {
        ec.entity.find('mantle.product.feature.ProductFeatureAppl')
                .condition('productId', productId).list().each { appl ->
            def feature = ec.entity.find('mantle.product.feature.ProductFeature')
                    .condition('productFeatureId', appl.productFeatureId).one()
            if (feature?.productFeatureTypeEnumId == 'PftSafetyFunction') {
                safetyFeatureList.add([productFeatureId: feature.productFeatureId, description: feature.description])
            }
        }
    }
    safetyFeatures = safetyFeatureList

    if (vectorList && safetyFeatureList) {
        status = 'REQUIRES_MITIGATION_REVIEW'
    } else if (vectorList) {
        status = 'NO_SAFETY_FUNCTION_ON_RECORD'
    } else {
        status = 'NO_EXPOSURE_VECTOR_ON_RECORD'
    }

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [deviceId: deviceId, status: status, vectors: vectors, safetyFeatures: safetyFeatures])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
